stmt.execute("""
    CREATE TABLE orders_bad (
        id INT PRIMARY KEY,
        user_name VARCHAR(100) NOT NULL,
        user_email VARCHAR(100) NOT NULL,
        product_name VARCHAR(100) NOT NULL,
        product_price DECIMAL(10, 2) NOT NULL
    )
    """);

// Jan Kowalski sklada 3 zamowienia - jego dane powtarzaja sie w KAZDYM wierszu!
stmt.execute("INSERT INTO orders_bad VALUES (1,'Jan Kowalski','jan@example.com','Klawiatura',199.99)");
stmt.execute("INSERT INTO orders_bad VALUES (2,'Jan Kowalski','jan@example.com','Mysz',89.50)");
stmt.execute("INSERT INTO orders_bad VALUES (3,'Jan Kowalski','jan@example.com','Monitor',899.00)");

ResultSet rs = stmt.executeQuery("SELECT COUNT(*) cnt, COUNT(DISTINCT user_email) unique_emails FROM orders_bad");
rs.next();
System.out.println("Wierszy: " + rs.getInt("cnt") + ", unikalnych emaili: " + rs.getInt("unique_emails"));
// Wierszy: 3, unikalnych emaili: 1  <- ten sam email zduplikowany 3-krotnie!

stmt.execute("CREATE TABLE users (id INT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(100) NOT NULL)");
stmt.execute("CREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(100) NOT NULL, price DECIMAL(10,2) NOT NULL)");
stmt.execute("""
    CREATE TABLE orders (
        id INT PRIMARY KEY, user_id INT NOT NULL,
        FOREIGN KEY (user_id) REFERENCES users(id)
    )
    """);
stmt.execute("""
    CREATE TABLE order_items (
        order_id INT NOT NULL, product_id INT NOT NULL,
        PRIMARY KEY (order_id, product_id),
        FOREIGN KEY (order_id) REFERENCES orders(id),
        FOREIGN KEY (product_id) REFERENCES products(id)
    )
    """);

// Dane Jana - JEDEN raz w users, produkty - JEDEN raz w products
stmt.execute("INSERT INTO users VALUES (1,'Jan Kowalski','jan@example.com')");
stmt.execute("INSERT INTO products VALUES (1,'Klawiatura',199.99),(2,'Mysz',89.50),(3,'Monitor',899.00)");
// Te same 3 zamowienia, ale ZERO duplikacji danych usera/produktu

ResultSet rs = stmt.executeQuery("SELECT COUNT(*) AS cnt FROM users");
rs.next();
System.out.println("Liczba fizycznych wierszy z danymi Jana: " + rs.getInt("cnt"));
// Liczba fizycznych wierszy z danymi Jana: 1
// -> zamiast 3-krotnej duplikacji (jak w orders_bad), dane Jana istnieja RAZ,
// niezaleznie od liczby jego zamowien. JOIN (Lesson14) pozwala je polaczyc z powrotem.
